145	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
146	  let cfg = loadConfig();
147	  const includedSystemWindows = cfg.mode === "climb";
148	  let env = await fetchEnvironment(includedSystemWindows);
149	  if (!env) return;
150	
151	  cfg = loadConfig();
152	  if (cfg.mode === "climb" && !includedSystemWindows) {
153	    env = await fetchEnvironment(true);
154	    if (!env) return;
155	  }
156	
157	  if (cfg.mode === "climb" && env.windows.length > 0) {
158	    const surfaces = env.windows.map((w) => w.rect);
159	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
160	  } else {
161	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
162	  }
163	}
