173	export function initEngine(pet: Pet): void {
174	  if (petRef) return;
175	  petRef = pet;
176	  stopRequested = false;
177	  lastMoveTs = Date.now();
178	  mood = "idle";
179	  sleeping = false;
180	  void loop();
