  1	// Shared window-position helpers. Both the engine (tick loop) and the physics
  2	// module (throw/fall) need to read and write the pet window's logical position;
  3	// centralizing it keeps the DPI conversion in one place and avoids two copies
  4	// of the same `outerPosition / scaleFactor` dance drifting apart.
  5	
  6	import { getCurrentWindow } from "@tauri-apps/api/window";
  7	import { LogicalPosition } from "@tauri-apps/api/dpi";
  8	import type { Point } from "./types";
  9	
 10	const win = getCurrentWindow();
 11	
 12	let cachedLogicalPos: Point | null = null;
 13	let cacheGeneration = 0;
 14	let pendingPositionRead: Promise<Point | null> | null = null;
 15	let pendingNativeDragMove: Promise<void> | null = null;
 16	let nativeDragActive = false;
 17	let trackingStarted = false;
 18	let pendingTracking: Promise<void> | null = null;
 19	
 20	function copyPoint(pos: Point): Point {
 21	  return { x: pos.x, y: pos.y };
 22	}
 23	
 24	function invalidatePosition(): number {
 25	  cacheGeneration += 1;
 26	  cachedLogicalPos = null;
 27	  return cacheGeneration;
 28	}
 29	
 30	function refreshNativeDragPosition(physical: Point): void {
 31	  const generationAtMove = invalidatePosition();
 32	  let update: Promise<void>;
 33	  update = win.scaleFactor()
 34	    .then((scaleFactor) => {
 35	      if (!nativeDragActive || generationAtMove !== cacheGeneration) return;
 36	      cachedLogicalPos = {
 37	        x: physical.x / scaleFactor,
 38	        y: physical.y / scaleFactor,
 39	      };
 40	    })
 41	    .catch(() => {
 42	      // Keep the cache invalid; the regular reader retries when it is needed.
 43	    })
 44	    .finally(() => {
 45	      if (pendingNativeDragMove === update) pendingNativeDragMove = null;
 46	    });
 47	  pendingNativeDragMove = update;
 48	}
 49	
 50	function startPositionTracking(): void {
 51	  if (trackingStarted || pendingTracking) return;
 52	  const movedRegistration = Promise.resolve().then(() =>
 53	    win.onMoved(({ payload }) => {
 54	      if (nativeDragActive) refreshNativeDragPosition(payload);
 55	    }),
 56	  );
 57	  const scaleRegistration = Promise.resolve().then(() =>
 58	    win.onScaleChanged(() => {
 59	      invalidatePosition();
 60	    }),
 61	  );
 62	  pendingTracking = Promise.allSettled([movedRegistration, scaleRegistration])
 63	    .then(([moved, scale]) => {
 64	      if (moved.status === "fulfilled" && scale.status === "fulfilled") {
 65	        trackingStarted = true;
 66	        return;
 67	      }
 68	      if (moved.status === "fulfilled") moved.value();
 69	      if (scale.status === "fulfilled") scale.value();
 70	    })
 71	    .finally(() => {
 72	      pendingTracking = null;
 73	    });
 74	}
 75	
 76	export function setNativeDragTracking(active: boolean): void {
 77	  if (nativeDragActive === active) return;
 78	  nativeDragActive = active;
 79	  invalidatePosition();
 80	}
 81	
 82	/// Current window position in LOGICAL pixels (DPI-divided). Returns null if the
 83	/// window or scaleFactor can't be read (e.g. window closing).
 84	export async function currentLogicalPos(): Promise<Point | null> {
 85	  startPositionTracking();
 86	  if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
 87	  while (pendingNativeDragMove) {
 88	    const update = pendingNativeDragMove;
 89	    await update;
 90	    if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
 91	    if (pendingNativeDragMove === update) break;
 92	  }
 93	  if (!pendingPositionRead) {
 94	    const generationAtReadStart = cacheGeneration;
 95	    pendingPositionRead = (async () => {
 96	      try {
 97	        const sf = await win.scaleFactor();
 98	        const p = await win.outerPosition();
 99	        if (generationAtReadStart !== cacheGeneration) {
100	          return cachedLogicalPos ? copyPoint(cachedLogicalPos) : null;
101	        }
102	        cachedLogicalPos = { x: p.x / sf, y: p.y / sf };
103	        return copyPoint(cachedLogicalPos);
104	      } catch {
105	        return null;
106	      } finally {
107	        pendingPositionRead = null;
108	      }
109	    })();
110	  }
111	  const pos = await pendingPositionRead;
112	  return pos ? copyPoint(pos) : null;
113	}
114	
115	/// Move the window to a logical-pixel position. Caller is responsible for
116	/// clamping to the work area first.
117	export async function setLogical(pos: Point): Promise<void> {
118	  const generationAtSetStart = invalidatePosition();
119	  await win.setPosition(new LogicalPosition(pos.x, pos.y));
120	  if (generationAtSetStart === cacheGeneration && !nativeDragActive) {
121	    cachedLogicalPos = copyPoint(pos);
122	  }
123	}
  1	// Movement engine: owns the tick loop, coordinates drag sampling, throw/fall
  2	// physics, and dispatches to the active movement mode.
  3	
  4	import { invoke } from "@tauri-apps/api/core";
  5	import type { Pet } from "../pet";
  6	import { fetchEnvironment } from "./environment";
  7	import { runMode } from "./modes";
  8	import {
  9	  applyFall,
 10	  applyThrow,
 11	  cancelThrow,
 12	  clearSamples,
 13	  isThrowing,
 14	  recordSample,
 15	  releaseVelocity,
 16	} from "./physics";
 17	import type { RoamMode } from "./types";
 18	import {
 19	  SLEEP_AFTER_MS,
 20	  SLEEP_ROW_DEFAULT,
 21	  THROW_MIN_SPEED,
 22	  TICK_MS,
 23	  clampToBounds,
 24	  loadConfig,
 25	  sleep,
 26	} from "./types";
 27	import { currentLogicalPos, setLogical, setNativeDragTracking } from "./window";
 28	
 29	/// Tick delay when the pet is resting / sleeping / stationary. The active
 30	/// TICK_MS (30ms) is only needed while the pet is actually moving — resting
 31	/// states (restUntil, sleep, stay mode) only need to check periodically whether
 32	/// to wake up. 200ms cuts IPC calls from 33/sec to 5/sec while idle, with no
 33	/// visible change (the pet resumes walking within one idle-tick of restUntil
 34	/// expiring, imperceptible for a desktop companion).
 35	const IDLE_TICK_MS = 200;
 36	
 37	let petRef: Pet | null = null;
 38	let dragging = false;
 39	let releasePending = false;
 40	let stopRequested = false;
 41	
 42	/// Mood drives two behaviors: pause roaming while the user needs to read the
 43	/// bubble (waiting / celebrate), and let the pet doze off when idle.
 44	let mood: string = "idle";
 45	let lastMoveTs = Date.now();
 46	let sleeping = false;
 47	
 48	/// Moods that freeze the pet so the bubble / celebration animation stays readable.
 49	const MOOD_PAUSES_ROAM = new Set(["waiting", "celebrate"]);
 50	
 51	function stop(): boolean { return stopRequested; }
 52	
 53	/// Called from main.ts after each mood evaluation. Non-idle moods wake the pet.
 54	export function setMood(m: string): void {
 55	  mood = m;
 56	  if (m !== "idle") wake();
 57	}
 58	
 59	function wake(): void {
 60	  if (!sleeping) return;
 61	  sleeping = false;
 62	  petRef?.clearRow();
 63	}
 64	
 65	function enterSleep(): void {
 66	  if (sleeping) return;
 67	  sleeping = true;
 68	  const bound = parseInt(localStorage.getItem("ap_bind_sleep") ?? "", 10);
 69	  const row = Number.isFinite(bound) && bound >= 0 ? bound : SLEEP_ROW_DEFAULT;
 70	  petRef?.setRow(row);
 71	}
 72	
 73	/// One engine tick. Priority: throw > drag-sample > drag-release > mood-pause > sleep > mode.
 74	/// Returns true when the pet is actively moving/interacting and needs the fast
 75	/// (30ms) tick; false when resting/sleeping/stationary so the loop can use the
 76	/// idle (200ms) tick and skip most IPC calls.
 77	async function tick(): Promise<boolean> {
 78	  if (isThrowing()) return true;
 79	  if (dragging) {
 80	    const pos = await currentLogicalPos();
 81	    if (pos) recordSample(pos);
 82	    return true;
 83	  }
 84	  if (releasePending) {
 85	    releasePending = false;
 86	    const vel = releaseVelocity();
 87	    clearSamples();
 88	    if (vel && Math.hypot(vel.vx, vel.vy) > THROW_MIN_SPEED) {
 89	      wake();
 90	      await handleDragRelease(vel);
 91	      return true;
 92	    }
 93	  }
 94	
 95	  // Mood-driven freeze: keep the pet still while the user needs to see the
 96	  // bubble or the celebrate burst. Throws and drags above still work.
 97	  if (MOOD_PAUSES_ROAM.has(mood)) {
 98	    wake();
 99	    petRef?.clearRow();
100	    return false;
101	  }
102	
103	  const cfg = loadConfig();
104	  if (!cfg.enabled || cfg.mode === "stay") {
105	    handleStationary();
106	    return false;
107	  }
108	
109	  wake();
110	  const moved = await stepMode(cfg.mode);
111	  if (!moved && mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
112	    enterSleep();
113	  }
114	  return moved;
115	}
116	
117	/// Run one mode step and apply it. Returns true if the pet actually moved.
118	async function stepMode(mode: RoamMode): Promise<boolean> {
119	  const env = await fetchEnvironment(mode === "climb");
120	  if (!env) return false;
121	  const pos = await currentLogicalPos();
122	  if (!pos) return false;
123	
